import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] firstLine = br.readLine().split(" ");
        int n = Integer.parseInt(firstLine[0]);
        int m = Integer.parseInt(firstLine[1]);
        String[] aLine = br.readLine().split(" ");
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = Integer.parseInt(aLine[i]);
        }

        List<Integer> subsetSumsFirst = new ArrayList<>();
        List<Integer> subsetSumsSecond = new ArrayList<>();
        int half = n / 2;

        computeFirstHalf(0, 0, a, m, half, subsetSumsFirst);
        computeSecondHalf(half, 0, a, m, n, subsetSumsSecond);

        Set<Integer> uniqueFirstSet = new HashSet<>(subsetSumsFirst);
        List<Integer> uniqueFirst = new ArrayList<>(uniqueFirstSet);
        Collections.sort(uniqueFirst);

        int maxSum = 0;
        for (int val : subsetSumsSecond) {
            int target = m - val;
            int pos = Collections.binarySearch(uniqueFirst, target);
            if (pos < 0) {
                pos = -pos - 1;
            }
            if (pos > 0) {
                int candidate = uniqueFirst.get(pos - 1) + val;
                if (candidate > maxSum) {
                    maxSum = candidate;
                }
            }
        }
        System.out.println(maxSum);
    }

    private static void computeFirstHalf(int index, int total, int[] a, int m, int half, List<Integer> subsetSumsFirst) {
        if (index == half) {
            subsetSumsFirst.add(total);
        } else {
            computeFirstHalf(index + 1, (total + a[index]) % m, a, m, half, subsetSumsFirst);
            computeFirstHalf(index + 1, total, a, m, half, subsetSumsFirst);
        }
    }

    private static void computeSecondHalf(int index, int total, int[] a, int m, int n, List<Integer> subsetSumsSecond) {
        if (index == n) {
            subsetSumsSecond.add(total);
        } else {
            computeSecondHalf(index + 1, (total + a[index]) % m, a, m, n, subsetSumsSecond);
            computeSecondHalf(index + 1, total, a, m, n, subsetSumsSecond);
        }
    }
}
